import csv
import io
import unittest
from exporter import export_rows

def parse(output):
    reader = csv.reader(io.StringIO(output))
    return list(reader)

class ExportTests(unittest.TestCase):
    def test_header(self):
        rows = parse(export_rows([]))
        self.assertEqual(rows[0], ["customer_id", "region"])

    def test_absent_region_is_na(self):
        rows = parse(export_rows([{"customer_id": "1"}]))
        self.assertEqual(rows[1], ["1", "NA"])

    def test_none_region_is_na(self):
        rows = parse(export_rows([{"customer_id": "2", "region": None}]))
        self.assertEqual(rows[1], ["2", "NA"])

    def test_empty_region_stays_empty(self):
        rows = parse(export_rows([{"customer_id": "3", "region": ""}]))
        self.assertEqual(rows[1], ["3", ""])

    def test_non_missing_region_preserved(self):
        rows = parse(export_rows([{"customer_id": "4", "region": "east"}]))
        self.assertEqual(rows[1], ["4", "east"])

    def test_customer_id_string_with_leading_zeros_preserved(self):
        rows = parse(export_rows([{"customer_id": "0007", "region": None}]))
        self.assertEqual(rows[1], ["0007", "NA"])

    def test_multiple_rows(self):
        rows = parse(export_rows([
            {"customer_id": "a", "region": None},
            {"customer_id": "b", "region": ""},
            {"customer_id": "c"},
            {"customer_id": "d", "region": "west"},
        ]))
        self.assertEqual(rows[1:], [
            ["a", "NA"],
            ["b", ""],
            ["c", "NA"],
            ["d", "west"],
        ])

if __name__ == "__main__":
    unittest.main()

